def score(program: str) -> float:
    import ast
    try:
        tree = ast.parse(program)
        nodes = list(ast.walk(tree))
        size = len(nodes)
        funcs = sum(1 for n in nodes if isinstance(n, ast.FunctionDef))

        s = size / 150.0 + funcs * 0.1
        return min(1.0, max(0.0, s))
    except:
        return 0.0

